/* Gearhouse shop management for the browser and a private local or MongoDB data store. */
(() => {
  'use strict';
  const STORAGE_KEY = 'gearhouse.parts.v1';
  const PAGE_NAMES = {dashboard:'Overview',inventory:'Inventory',pos:'New sale',sales:'Sales & receipts',orders:'Customer orders',customers:'Customers',storefront:'Parts catalog',settings:'Shop settings'};
  const CATEGORIES = ['Engine','Brakes','Electrical','Filters','Suspension','Transmission','Body & exterior','Cooling','Accessories','Other'];
  const CURRENCY_OPTIONS = ['INR','USD','AED','GBP','EUR'];
  const DEFAULTS = {settings:{shopName:'GEARHOUSE',phone:'',email:'',address:'',taxRate:0,currency:'INR',lowStockDefault:5,receiptNote:'Thank you for choosing our shop. Please keep this receipt for your records.'},products:[],sales:[],movements:[],customers:[],orders:[]};
  let db = loadDB();
  let page = 'dashboard';
  let inventoryFilter = 'all';
  let salesFilter = 'all';
  let orderFilter = 'open';
  let posQuery = '';
  let storeQuery = '';
  let customerQuery = '';
  let inventoryQuery = '';
  let cart = [];
  let receiptSaleId = null;
  const serverMode = location.protocol === 'http:' || location.protocol === 'https:';
  let isAuthenticated = false;
  let storageMode = "local-folder";
  let serverSaveQueue = Promise.resolve();

  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const uid = () => (crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function loadDB(){
    try { const raw=localStorage.getItem(STORAGE_KEY); if(!raw) return structuredClone(DEFAULTS); const parsed=JSON.parse(raw); return {...structuredClone(DEFAULTS),...parsed,settings:{...DEFAULTS.settings,...(parsed.settings||{})},products:Array.isArray(parsed.products)?parsed.products:[],sales:Array.isArray(parsed.sales)?parsed.sales:[],movements:Array.isArray(parsed.movements)?parsed.movements:[],customers:Array.isArray(parsed.customers)?parsed.customers:[],orders:Array.isArray(parsed.orders)?parsed.orders:[]}; }
    catch(err){ console.error('Could not read saved shop data',err); return structuredClone(DEFAULTS); }
  }
  function saveDB(){
    try{ localStorage.setItem(STORAGE_KEY,JSON.stringify(db)); }catch(err){ toast('Could not save in this browser. Check available storage.','error'); }
    if(serverMode&&isAuthenticated){
      const snapshot=JSON.stringify(db);
      serverSaveQueue=serverSaveQueue.then(async()=>{
        const response=await fetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:snapshot,credentials:'same-origin'});
        if(response.status===401){isAuthenticated=false;showLogin('Your session expired. Sign in again to continue.');throw new Error('Session expired');}
        if(!response.ok){const result=await response.json().catch(()=>({}));toast(result.error||'Could not save to the server. Your browser copy is still available.','error');}
      }).catch(error=>{if(error.message!=='Session expired')console.error('Server save failed:',error);});
    }
  }
  function money(n){ const amount=Number(n)||0; try{return new Intl.NumberFormat(undefined,{style:'currency',currency:db.settings.currency||'INR',maximumFractionDigits:2}).format(amount);}catch{return `${db.settings.currency||'INR'} ${amount.toFixed(2)}`;} }
  function dateOnly(v){const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString(undefined,{day:'2-digit',month:'short',year:'numeric'});}
  function dateTime(v){const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString(undefined,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});}
  function localDateISO(value=new Date()){const d=new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function todayISO(){return localDateISO();}
  function toast(message,type=''){const root=$('#toast-root');const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;root.append(el);setTimeout(()=>el.remove(),3200);}
  function productById(id){return db.products.find(p=>p.id===id);}
  function activeProducts(){return db.products.filter(p=>p.active!==false);}
  function lowThreshold(p){return Number(p.reorderPoint ?? db.settings.lowStockDefault ?? 5);}
  function stockState(p){if(Number(p.quantity)<=0)return 'out';if(Number(p.quantity)<=lowThreshold(p))return 'low';return 'ok';}
  function stockLabel(p){const s=stockState(p);return s==='out'?'Out of stock':s==='low'?'Low stock':'In stock';}
  function iconFor(p){const s=`${p.category||''} ${p.name||''}`.toLowerCase();if(/brake|disc|pad/.test(s))return '◉';if(/filter/.test(s))return '▥';if(/oil|engine|piston/.test(s))return '⚙';if(/light|electrical|battery|plug/.test(s))return 'ϟ';if(/wheel|tyre|tire|suspension/.test(s))return '◌';if(/mirror|body|bumper/.test(s))return '⬡';if(/cool|radiator/.test(s))return '♨';return '⚙';}
  function setPage(next){ if(!PAGE_NAMES[next])return; page=next; receiptSaleId=null; $$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page)); $('#crumb-page').textContent=PAGE_NAMES[page]; $('#sidebar').classList.remove('open'); renderPage(); window.scrollTo({top:0,behavior:'smooth'}); }
  function pageHead(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`;}
  function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-head"><div><div class="panel-title">${title}</div>${subtitle?`<div class="panel-subtitle">${subtitle}</div>`:''}</div>${action}</div>${body}</section>`;}
  function stat(label,value,foot,icon){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
  function renderPage(){
    const host=$('#page-content');
    const renderers={dashboard:renderDashboard,inventory:renderInventory,pos:renderPOS,sales:renderSales,orders:renderOrders,customers:renderCustomers,storefront:renderStorefront,settings:renderSettings};
    host.innerHTML=renderers[page]();
    updateNavCount();
  }
  function updateNavCount(){const n=db.products.filter(p=>p.active!==false&&stockState(p)!=='ok').length;const badge=$('#nav-low-count');badge.textContent=n;badge.classList.toggle('hidden',n===0);const orderBadge=$('#nav-order-count');if(orderBadge){const waiting=db.orders.filter(o=>['new','contacted','ready'].includes(o.status)).length;orderBadge.textContent=waiting;orderBadge.classList.toggle('hidden',waiting===0);}}

  function renderDashboard(){
    const day=todayISO();const todays=db.sales.filter(s=>localDateISO(s.date)===day&&s.status!=='void');const revenue=todays.reduce((a,s)=>a+s.total,0);const low=db.products.filter(p=>p.active!==false&&stockState(p)!=='ok');const inventoryValue=db.products.filter(p=>p.active!==false).reduce((a,p)=>a+(Number(p.cost)||0)*(Number(p.quantity)||0),0);const units=db.products.filter(p=>p.active!==false).reduce((a,p)=>a+(Number(p.quantity)||0),0);
    const latest=[...db.sales].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,5);
    const movementLatest=[...db.movements].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,5);
    const activity=latest.map(s=>`<div class="activity-row"><div class="activity-badge">↗</div><div class="activity-copy"><strong>${esc(s.customer?.name||'Walk-in customer')} · ${esc(s.receiptNo)}</strong><small>${dateTime(s.date)} · ${s.items.length} part${s.items.length===1?'':'s'}</small></div><span class="activity-amount">${money(s.total)}</span></div>`).join('')||movementLatest.map(m=>`<div class="activity-row"><div class="activity-badge">${m.delta>=0?'＋':'↘'}</div><div class="activity-copy"><strong>${esc(m.productName)} · ${esc(m.reason)}</strong><small>${dateTime(m.date)} · ${m.delta>=0?'+':''}${m.delta} units</small></div><span class="activity-amount">${m.delta>=0?'+':''}${m.delta}</span></div>`).join('')||`<div class="empty-state"><div class="empty-icon">↗</div><strong>Nothing moving yet</strong><p>Your sales and stock activity will show here.</p></div>`;
    const alerts=low.slice().sort((a,b)=>a.quantity-b.quantity).slice(0,5).map(p=>`<div class="alert-row"><div class="alert-symbol">!</div><div><strong>${esc(p.name)}</strong><small>${esc(p.sku||'No SKU')} · reorder at ${lowThreshold(p)}</small></div><span class="alert-qty">${p.quantity} left</span></div>`).join('')||`<div class="empty-state" style="padding:25px 10px"><div class="empty-icon">✓</div><strong>Stock looks healthy</strong><p>Low-stock items will appear here.</p></div>`;
    const chart=renderSalesChart();
    return `${pageHead('SHOP PULSE','Good '+greeting()+',','Here’s what’s happening in your shop today.',`<button class="btn" data-go="inventory">＋ Add part</button><button class="btn dark" data-go="pos">＋ New sale</button>`)}
      <div class="stats-grid">${stat("TODAY'S SALES",money(revenue),`${todays.length} completed sale${todays.length===1?'':'s'} today`,'↗')}${stat('ACTIVE PARTS',activeProducts().length,`${units.toLocaleString()} units currently on hand`,'⚙')}${stat('LOW STOCK',low.length,low.length?`<span class="up">Needs a restock check</span>`:'All active parts above reorder point','!')}${stat('STOCK AT COST',money(inventoryValue),'Based on the cost entered for each part','▤')}</div>
      <div class="dashboard-grid"><div>${panel('Sales rhythm','Revenue from completed sales · last 7 days',`<div class="panel-body"><div class="chart-legend"><i class="legend-mark"></i> Sales</div>${chart}</div>`)}<div class="section-gap">${panel('Recent activity','Latest sales and inventory movement',`<div class="panel-body"><div class="activity-list">${activity}</div></div>`,`<button class="text-action" data-go="sales">View sales →</button>`)}</div></div>
      <div>${panel('Restock watch',`${low.length} item${low.length===1?'':'s'} at or below reorder point`,`<div class="panel-body"><div class="alert-list">${alerts}</div></div>`,`<button class="text-action" data-go="inventory">Inventory →</button>`)}<div class="section-gap">${panel('Quick actions','Keep the counter moving',`<div class="panel-body" style="display:grid;gap:8px"><button class="btn" data-go="pos">＋ Create a sale <span style="margin-left:auto">→</span></button><button class="btn" data-action="new-product">⚙ Add a part <span style="margin-left:auto">→</span></button><button class="btn" data-go="storefront">◫ Browse parts catalog <span style="margin-left:auto">→</span></button><div class="inline-note">Parts, receipts, and movement history stay connected automatically.</div></div>`)}</div></div></div>`;
  }
  function greeting(){const h=new Date().getHours();return h<12?'morning':h<17?'afternoon':'evening';}
  function renderSalesChart(){
    const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);days.push({iso:localDateISO(d),label:d.toLocaleDateString(undefined,{weekday:'short'}),value:0});}
    db.sales.filter(s=>s.status!=='void').forEach(s=>{const x=days.find(d=>d.iso===localDateISO(s.date));if(x)x.value+=s.total;});
    const max=Math.max(...days.map(d=>d.value),1);const pts=days.map((d,i)=>`${28+i*85},${180-(d.value/max*140)}`).join(' ');const area=`M 28 180 L ${days.map((d,i)=>`${28+i*85} ${180-d.value/max*140}`).join(' L ')} L 538 180 Z`;
    const dots=days.map((d,i)=>`<circle cx="${28+i*85}" cy="${180-d.value/max*140}" r="3.5" fill="#fff" stroke="#557d42" stroke-width="2"><title>${esc(d.label)}: ${money(d.value)}</title></circle>`).join('');
    return `<div class="chart-wrap"><svg viewBox="0 0 566 205" role="img" aria-label="Sales chart for the last seven days"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#8eb771" stop-opacity=".22"/><stop offset="100%" stop-color="#8eb771" stop-opacity="0"/></linearGradient></defs><line class="chart-grid" x1="24" y1="40" x2="540" y2="40"/><line class="chart-grid" x1="24" y1="90" x2="540" y2="90"/><line class="chart-grid" x1="24" y1="140" x2="540" y2="140"/><path class="chart-area" d="${area}"/><polyline class="chart-line" points="${pts}"/>${dots}</svg></div><div class="chart-labels">${days.map(d=>`<span>${esc(d.label)}</span>`).join('')}</div>`;
  }

  function stockPill(p){return `<span class="stock-pill ${stockState(p)}">${Number(p.quantity)||0} · ${stockLabel(p)}</span>`;}
  function partCell(p){return `<div class="part-cell"><div class="part-thumb">${iconFor(p)}</div><div class="part-name"><strong>${esc(p.name)}</strong><small>${esc(p.sku||'NO SKU')}</small></div></div>`;}
  function renderInventory(){
    const all=db.products.filter(p=>p.active!==false), archived=db.products.filter(p=>p.active===false);let rows=(inventoryFilter==='archived'?archived:all).filter(p=>`${p.name} ${p.sku} ${p.brand} ${p.fitment} ${p.category}`.toLowerCase().includes(inventoryQuery.toLowerCase()));if(inventoryFilter==='low')rows=rows.filter(p=>stockState(p)!=='ok');if(inventoryFilter==='out')rows=rows.filter(p=>stockState(p)==='out');
    const table=rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Part</th><th>Category</th><th>Vehicle fitment</th><th>Price</th><th>On hand</th><th>Location</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${partCell(p)}</td><td>${esc(p.category||'Other')}</td><td>${esc(p.fitment||'—')}</td><td class="mono">${money(p.price)}</td><td>${stockPill(p)}</td><td>${esc(p.location||'—')}</td><td><div class="row-actions">${p.active===false?`<button class="text-action" data-action="restore-product" data-id="${p.id}">Restore</button>`:`<button class="text-action" data-action="adjust-stock" data-id="${p.id}">Stock</button><button class="text-action" data-action="edit-product" data-id="${p.id}">Edit</button><button class="text-action" data-action="archive-product" data-id="${p.id}">Archive</button>`}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">⚙</div><strong>${all.length?'No matching parts':'Your inventory starts here'}</strong><p>${all.length?'Try another search or stock filter.':'Add parts, prices, and opening quantities to begin tracking.'}</p>${all.length?'':`<button class="btn dark" data-action="new-product">＋ Add your first part</button>`}</div>`;
    return `${pageHead('PARTS ROOM','Inventory','Every part, price, and quantity in one place.',`<button class="btn" data-action="export-products">↓ Export CSV</button><button class="btn dark" data-action="new-product">＋ Add part</button>`)}
      <div class="stats-grid">${stat('ACTIVE PARTS',all.length,`${all.filter(p=>p.quantity>0).length} parts in stock`,'⚙')}${stat('TOTAL UNITS',all.reduce((a,p)=>a+(+p.quantity||0),0),'Across all active SKUs','▤')}${stat('LOW / OUT',all.filter(p=>stockState(p)!=='ok').length,'At or below reorder point','!')}${stat('RETAIL VALUE',money(all.reduce((a,p)=>a+(+p.price||0)*(+p.quantity||0),0)),'Potential value at current prices','₹')}</div>
      <section class="panel"><div class="panel-head"><div><div class="panel-title">Parts inventory</div><div class="panel-subtitle">${rows.length} result${rows.length===1?'':'s'} · Stock changes are recorded in the movement history</div></div><div class="section-toolbar"><div class="search-box"><input id="inventory-search" value="${esc(inventoryQuery)}" placeholder="Search name, SKU, vehicle…" /></div><select id="inventory-filter" class="select-filter"><option value="all" ${inventoryFilter==='all'?'selected':''}>Active stock</option><option value="low" ${inventoryFilter==='low'?'selected':''}>Low stock</option><option value="out" ${inventoryFilter==='out'?'selected':''}>Out of stock</option><option value="archived" ${inventoryFilter==='archived'?'selected':''}>Archived (${archived.length})</option></select></div></div>${table}<div class="pagination-line">Showing ${rows.length} ${inventoryFilter==='archived'?'archived':'active'} parts</div></section>
      <div class="section-gap">${panel('Recent stock movements','Receipts, sales, and manual adjustments',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Part</th><th>Change</th><th>Reason</th><th>New balance</th></tr></thead><tbody>${[...db.movements].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,8).map(m=>`<tr><td>${dateTime(m.date)}</td><td>${esc(m.productName)}</td><td class="mono" style="color:${m.delta<0?'#b44d3d':'#55783f'}">${m.delta>0?'+':''}${m.delta}</td><td>${esc(m.reason)}</td><td class="mono">${m.after}</td></tr>`).join('')||`<tr><td colspan="5" class="inline-note">Stock movement records will appear as inventory changes.</td></tr>`}</tbody></table></div>`)}</div>`;
  }

  function productOptions(query=''){return activeProducts().filter(p=>p.quantity>0&&`${p.name} ${p.sku} ${p.brand} ${p.fitment}`.toLowerCase().includes(query.toLowerCase()));}
  function renderPOS(){
    const products=productOptions(posQuery);const cards=products.length?products.map(p=>`<button class="product-card" data-action="cart-add" data-id="${p.id}" aria-label="Add ${esc(p.name)}"><div class="product-art">${iconFor(p)}</div><strong>${esc(p.name)}</strong><small>${esc(p.sku||p.category||'Part')} · ${p.quantity} available</small><div class="product-bottom"><b>${money(p.price)}</b><em>＋ Add</em></div></button>`).join(''):`<div class="empty-state" style="grid-column:1/-1"><div class="empty-icon">⌕</div><strong>No parts available</strong><p>Add stock or change your search.</p><button class="btn" data-action="new-product">＋ Add a part</button></div>`;
    return `${pageHead('COUNTER SALES','New sale','Add the parts, capture customer details, and issue a receipt.',`<button class="btn" data-go="inventory">View inventory</button>`)}<div class="pos-layout"><section class="panel pos-catalog"><div class="panel-head"><div><div class="panel-title">Choose parts</div><div class="panel-subtitle">Only active parts with stock are available</div></div><div class="search-box"><input id="pos-search" value="${esc(posQuery)}" placeholder="Find a part…" /></div></div><div class="product-grid">${cards}</div></section>${renderCartPanel(true)}</div>`;
  }
  function cartTotals(){const subtotal=cart.reduce((a,l)=>a+l.price*l.qty,0);const discount=Math.max(0,Number($('#discount-input')?.value)||0);const taxable=Math.max(0,subtotal-discount);const tax=taxable*(Number(db.settings.taxRate)||0)/100;return {subtotal,discount,tax,total:taxable+tax};}
  function renderCartPanel(admin){
    const lines=cart.length?cart.map(l=>`<div class="cart-line"><div><div class="cart-line-name">${esc(l.name)}</div><div class="cart-line-meta">${money(l.price)} each</div><div class="qty-control"><button data-action="cart-qty" data-id="${l.productId}" data-step="-1" aria-label="Decrease quantity">−</button><span>${l.qty}</span><button data-action="cart-qty" data-id="${l.productId}" data-step="1" aria-label="Increase quantity">＋</button></div></div><div class="cart-line-right"><strong class="mono">${money(l.price*l.qty)}</strong><button class="remove-line" data-action="cart-remove" data-id="${l.productId}" aria-label="Remove">×</button></div></div>`).join(''):`<div class="cart-empty">Your sale is empty.<br/>Choose parts to add them here.</div>`;
    const totals=cartTotals();
    return `<section class="panel sale-panel"><div class="panel-head"><div><div class="panel-title">${admin?'Sale details':'Your order'}</div><div class="panel-subtitle">${cart.length} line${cart.length===1?'':'s'} · ${cart.reduce((a,l)=>a+l.qty,0)} unit${cart.reduce((a,l)=>a+l.qty,0)===1?'':'s'}</div></div><button class="text-action" data-action="cart-clear">Clear</button></div><div class="panel-body">${admin?`<div class="customer-fields"><div class="field"><label for="customer-name">CUSTOMER NAME</label><input id="customer-name" placeholder="Walk-in customer" /></div><div class="field"><label for="customer-phone">PHONE</label><input id="customer-phone" inputmode="tel" placeholder="Optional" /></div><div class="field"><label for="customer-email">EMAIL</label><input id="customer-email" type="email" placeholder="Optional" /></div><div class="field"><label for="payment-method">PAYMENT</label><select id="payment-method"><option>Cash</option><option>UPI</option><option>Card</option><option>Bank transfer</option><option>Other</option></select></div></div>`:''}<div class="cart-items">${lines}</div><div class="field" style="margin-bottom:10px"><label for="discount-input">DISCOUNT AMOUNT</label><input id="discount-input" type="number" min="0" step="0.01" value="0" placeholder="0.00" /></div><div class="totals"><div class="total-row"><span>Subtotal</span><strong id="subtotal-val">${money(totals.subtotal)}</strong></div><div class="total-row"><span>Discount</span><strong id="discount-val">− ${money(totals.discount)}</strong></div><div class="total-row"><span>Tax ${db.settings.taxRate?`(${Number(db.settings.taxRate)}%)`:'(not configured)'}</span><strong id="tax-val">${money(totals.tax)}</strong></div><div class="total-row grand"><span>Total due</span><strong id="grand-val">${money(totals.total)}</strong></div></div>${admin?`<button class="btn dark checkout-btn" data-action="checkout" ${cart.length?'':'disabled'}>Complete sale <span style="margin-left:auto;color:var(--green)">→</span></button><div class="inline-note" style="margin-top:9px;text-align:center">Stock is deducted and a printable receipt is created.</div>`:`<button class="btn dark checkout-btn" data-action="catalog-checkout" ${cart.length?'':'disabled'}>Continue to checkout →</button><div class="inline-note" style="margin-top:9px;text-align:center">Final sale and payment are completed at the shop counter.</div>`}</div></section>`;
  }

  function renderSales(){
    if(receiptSaleId){const sale=db.sales.find(s=>s.id===receiptSaleId);if(sale)return `${pageHead('SALE DETAIL','Receipt','Review the transaction, print a customer copy, or void this sale.',`<button class="btn" data-go="sales">← Back to sales</button><button class="btn dark" data-action="print-receipt">Print receipt</button>`)}${renderReceipt(sale)}`;}
    const sales=[...db.sales].sort((a,b)=>new Date(b.date)-new Date(a.date));const filtered=sales.filter(s=>salesFilter==='all'||s.status===salesFilter);const total=sales.filter(s=>s.status!=='void').reduce((a,s)=>a+s.total,0);const table=filtered.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Receipt</th><th>Date</th><th>Customer</th><th>Items</th><th>Payment</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${filtered.map(s=>`<tr><td class="mono">${esc(s.receiptNo)}</td><td>${dateTime(s.date)}</td><td>${esc(s.customer?.name||'Walk-in customer')}<small style="display:block;color:#98a199;margin-top:4px">${esc(s.customer?.phone||'')}</small></td><td>${s.items.reduce((a,i)=>a+i.qty,0)} units</td><td>${esc(s.paymentMethod)}</td><td class="mono">${money(s.total)}</td><td><span class="status-pill ${s.status==='void'?'void':'paid'}">${s.status==='void'?'Voided':'Paid'}</span></td><td><button class="text-action" data-action="view-receipt" data-id="${s.id}">Receipt →</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">▧</div><strong>No sales ${salesFilter==='all'?'yet':`marked ${salesFilter}`}</strong><p>Completed sales and their receipts will be kept here.</p><button class="btn dark" data-go="pos">＋ Create a sale</button></div>`;
    return `${pageHead('TRANSACTION BOOK','Sales & receipts','A searchable record of every checkout and customer receipt.',`<button class="btn" data-action="export-sales">↓ Export CSV</button><button class="btn dark" data-go="pos">＋ New sale</button>`)}<div class="stats-grid">${stat('COMPLETED SALES',sales.filter(s=>s.status!=='void').length,'Voided sales are excluded','▧')}${stat('REVENUE TO DATE',money(total),'Net of voided receipts','↗')}${stat('AVERAGE SALE',money(sales.filter(s=>s.status!=='void').length?total/sales.filter(s=>s.status!=='void').length:0),'Across completed transactions','₹')}${stat('VOIDED',sales.filter(s=>s.status==='void').length,'Voids restore sold stock','↶')}</div><section class="panel"><div class="panel-head"><div><div class="panel-title">All transactions</div><div class="panel-subtitle">${filtered.length} of ${sales.length} receipts</div></div><div class="filter-tabs"><button class="tab-btn ${salesFilter==='all'?'active':''}" data-action="sales-filter" data-value="all">All</button><button class="tab-btn ${salesFilter==='paid'?'active':''}" data-action="sales-filter" data-value="paid">Completed</button><button class="tab-btn ${salesFilter==='void'?'active':''}" data-action="sales-filter" data-value="void">Voided</button></div></div>${table}</section>`;
  }
  function renderOrders(){
    const all=[...db.orders].sort((a,b)=>new Date(b.date)-new Date(a.date));
    const open=all.filter(o=>['new','contacted','ready'].includes(o.status));
    const rows=all.filter(o=>orderFilter==='all'||(orderFilter==='open'?['new','contacted','ready'].includes(o.status):['completed','cancelled'].includes(o.status)));
    const cards=rows.length?rows.map(o=>{
      const phone=String(o.customer?.phone||'');const phoneHref=phone.replace(/[^+\d]/g,'');
      const statusLabel={new:'New request',contacted:'Contacted',ready:'Ready for pickup',completed:'Picked up',cancelled:'Cancelled'}[o.status]||o.status;
      const next=o.status==='new'?'contacted':o.status==='contacted'?'ready':o.status==='ready'?'completed':null;
      const nextLabel=o.status==='new'?'Mark contacted':o.status==='contacted'?'Ready for pickup':o.status==='ready'?'Mark picked up':null;
      return `<article class="panel" style="margin-bottom:12px"><div class="panel-head"><div><div class="panel-title">${esc(o.orderNo)}</div><div class="panel-subtitle">${dateTime(o.date)} · <span class="status-pill ${o.status==='completed'?'paid':o.status==='cancelled'?'void':'pending'}">${esc(statusLabel)}</span></div></div><div class="section-toolbar">${next?`<button class="btn dark" data-action="set-order-status" data-id="${esc(o.id)}" data-status="${next}">${nextLabel} →</button>`:''}${!['completed','cancelled'].includes(o.status)?`<button class="btn danger small" data-action="set-order-status" data-id="${esc(o.id)}" data-status="cancelled">Cancel</button>`:''}<a class="text-action" href="tel:${esc(phoneHref)}">Call customer ↗</a></div></div><div class="panel-body"><div class="order-summary"><div><strong>${esc(o.customer?.name||'Customer')}</strong><small><a href="tel:${esc(phoneHref)}">${esc(phone)}</a>${o.customer?.email?` · ${esc(o.customer.email)}`:''}</small></div><strong class="mono">${money(o.total)}</strong></div><div class="order-lines">${o.items.map(i=>`<div class="order-line"><span>${esc(i.name)}${i.sku?` <small>· ${esc(i.sku)}</small>`:''}</span><span>${i.qty} × ${money(i.price)} <b>${money(i.qty*i.price)}</b></span></div>`).join('')}</div>${o.note?`<div class="order-note"><strong>Customer note / vehicle:</strong> ${esc(o.note)}</div>`:''}<div class="inline-note" style="margin-top:11px">Pickup request only. Confirm availability and price with the customer, then record the paid sale at checkout.</div></div></article>`;
    }).join(''):`<section class="panel"><div class="empty-state"><div class="empty-icon">▣</div><strong>${all.length?'No orders in this view':'No customer requests yet'}</strong><p>${all.length?'Choose another filter to see other requests.':'New pickup requests from the public shop will appear here.'}<br/>The public catalog is available at <a href="/" target="_blank" rel="noopener">the shop page ↗</a></p></div></section>`;
    return `${pageHead('CUSTOMER REQUESTS','Customer orders','Review pickup requests, check vehicle fitment, and contact customers.',`<a class="btn" href="/" target="_blank" rel="noopener">Open customer shop ↗</a>`)}<div class="stats-grid">${stat('OPEN REQUESTS',open.length,'Waiting for confirmation or pickup','▣')}${stat('NEW TODAY',all.filter(o=>localDateISO(o.date)===todayISO()).length,'Requests submitted today','↗')}${stat('PICKED UP',all.filter(o=>o.status==='completed').length,'Completed at the shop','✓')}${stat('ESTIMATED OPEN VALUE',money(open.reduce((sum,o)=>sum+(Number(o.total)||0),0)),'Customer-requested parts, not paid sales','₹')}</div><section class="panel"><div class="panel-head"><div><div class="panel-title">Pickup requests</div><div class="panel-subtitle">${rows.length} request${rows.length===1?'':'s'} · No online payment is collected</div></div><select id="orders-filter" class="select-filter"><option value="open" ${orderFilter==='open'?'selected':''}>Open requests</option><option value="closed" ${orderFilter==='closed'?'selected':''}>Completed / cancelled</option><option value="all" ${orderFilter==='all'?'selected':''}>All requests</option></select></div></section><div style="margin-top:12px">${cards}</div>`;
  }
  function renderReceipt(s){
    return `<div class="receipt-paper"><div class="receipt-top"><div class="receipt-brand">${esc(db.settings.shopName||'GEARHOUSE')}<small>SPARE PARTS · SALES RECEIPT</small></div><div class="receipt-meta"><strong>${esc(s.receiptNo)}</strong><br/>${dateTime(s.date)}<br/>${esc(s.paymentMethod)} · ${s.status==='void'?'VOIDED':'PAID'}</div></div><div class="receipt-customer"><div><strong>Customer</strong><br/>${esc(s.customer?.name||'Walk-in customer')}<br/>${esc(s.customer?.phone||'')}${s.customer?.email?`<br/>${esc(s.customer.email)}`:''}</div><div style="text-align:right">${esc(db.settings.address||'')}${db.settings.phone?`<br/>${esc(db.settings.phone)}`:''}</div></div><table class="receipt-table"><thead><tr><th>Part</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>${s.items.map(i=>`<tr><td>${esc(i.name)}<small style="display:block;color:#929b93;margin-top:3px">${esc(i.sku||'')}</small></td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(i.price*i.qty)}</td></tr>`).join('')}</tbody></table><div class="receipt-summary"><div class="total-row"><span>Subtotal</span><strong>${money(s.subtotal)}</strong></div><div class="total-row"><span>Discount</span><strong>− ${money(s.discount)}</strong></div><div class="total-row"><span>Tax ${s.taxRate?`(${s.taxRate}%)`:''}</span><strong>${money(s.tax)}</strong></div><div class="total-row grand"><span>Total paid</span><strong>${money(s.total)}</strong></div></div><div class="receipt-note">${s.status==='void'?'THIS RECEIPT HAS BEEN VOIDED.':esc(db.settings.receiptNote||'Thank you for your purchase.')}<br/>${esc(db.settings.email||'')}</div>${s.status!=='void'?`<div class="no-print" style="text-align:right;margin-top:15px"><button class="btn danger small" data-action="void-sale" data-id="${s.id}">Void sale & restore stock</button></div>`:''}</div>`;
  }

  function customersFromSales(){
    const map=new Map(db.customers.map(c=>[c.key,{...c,visits:0,totalSpent:0,lastVisit:''}]));
    db.sales.filter(s=>s.status!=='void'&&s.customer?.phone).forEach(s=>{const key=s.customer.phone.replace(/\D/g,'');if(!key)return;let c=map.get(key);if(!c){c={key,name:s.customer.name||'Customer',phone:s.customer.phone,email:s.customer.email||'',visits:0,totalSpent:0,lastVisit:s.date};map.set(key,c);}c.visits++;c.totalSpent+=s.total;if(new Date(s.date)>new Date(c.lastVisit))c.lastVisit=s.date;});
    return [...map.values()].filter(c=>`${c.name} ${c.phone} ${c.email}`.toLowerCase().includes(customerQuery.toLowerCase())).sort((a,b)=>new Date(b.lastVisit)-new Date(a.lastVisit));
  }
  function renderCustomers(){const customers=customersFromSales();const all=customersFromSalesNoFilter();const spend=all.reduce((a,c)=>a+c.totalSpent,0);const rows=customers.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Phone</th><th>Visits</th><th>Lifetime spend</th><th>Last seen</th><th></th></tr></thead><tbody>${customers.map(c=>`<tr><td><div class="part-cell"><div class="avatar">${esc((c.name||'?').split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase())}</div><div class="part-name"><strong>${esc(c.name)}</strong><small>${esc(c.email||'Customer')}</small></div></div></td><td>${esc(c.phone)}</td><td>${c.visits}</td><td class="mono">${money(c.totalSpent)}</td><td>${dateOnly(c.lastVisit)}</td><td><button class="text-action" data-action="customer-history" data-phone="${esc(c.phone)}">Sales →</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">♙</div><strong>No customer history yet</strong><p>Customer records are collected when you save a sale with a phone number.</p><button class="btn dark" data-go="pos">＋ Create a sale</button></div>`;
    return `${pageHead('CUSTOMER BOOK','Customers','Know who comes back and what they have purchased.',`<div class="search-box"><input id="customer-search" value="${esc(customerQuery)}" placeholder="Search customers…" /></div>`)}<div class="stats-grid">${stat('CUSTOMERS',all.length,'Unique phone numbers on paid sales','♙')}${stat('RETURNING',all.filter(c=>c.visits>1).length,'More than one completed purchase','↻')}${stat('CUSTOMER SALES',money(spend),'Net of voided transactions','₹')}${stat('AVG. LIFETIME',money(all.length?spend/all.length:0),'Per identified customer','↗')}</div><section class="panel"><div class="panel-head"><div><div class="panel-title">Customer directory</div><div class="panel-subtitle">Only customers with a phone number are grouped into a profile</div></div><button class="btn small" data-action="export-customers">↓ Export CSV</button></div>${rows}</section>`;
  }
  function customersFromSalesNoFilter(){const q=customerQuery;customerQuery='';const r=customersFromSales();customerQuery=q;return r;}

  function renderStorefront(){const items=activeProducts().filter(p=>p.quantity>0&&`${p.name} ${p.sku} ${p.brand} ${p.fitment} ${p.category}`.toLowerCase().includes(storeQuery.toLowerCase()));return `${pageHead('CUSTOMER CATALOG','Parts catalog','A browsable catalog connected to your active stock.',`<button class="btn" data-go="inventory">Manage inventory</button>`)}<div class="store-hero"><div><div class="eyebrow" style="color:#afc4a5">${esc(db.settings.shopName||'GEARHOUSE')} · PARTS COUNTER</div><h2>Find the right part.<br/>Get back on the road.</h2><p>Browse what’s currently available at the shop.</p></div><div class="brand-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M5 8.5 16 3l11 5.5v15L16 29 5 23.5z"/><path d="M5.5 8.7 16 14l10.5-5.3M16 14v14"/></svg></div></div><div class="store-layout"><section><div class="panel-head" style="padding:0 0 12px;border:0"><div><div class="panel-title">Available parts</div><div class="panel-subtitle">${items.length} in-stock item${items.length===1?'':'s'}</div></div><div class="search-box"><input id="store-search" value="${esc(storeQuery)}" placeholder="Search parts or vehicle…" /></div></div>${items.length?`<div class="store-products">${items.map(p=>`<article class="store-item"><div class="product-art">${iconFor(p)}</div><div class="part-name"><strong>${esc(p.name)}</strong><small>${esc(p.sku||p.category||'Part')} · ${esc(p.fitment||'Ask us to confirm fitment')}</small></div><div class="product-bottom"><span class="store-price">${money(p.price)}</span><em>${p.quantity} available</em></div><button class="btn add-to-cart" data-action="cart-add" data-id="${p.id}">＋ Add to order</button></article>`).join('')}</div>`:`<div class="panel"><div class="empty-state"><div class="empty-icon">◫</div><strong>No in-stock parts to show</strong><p>Add stock in inventory to make parts visible here.</p></div></div>`}</section>${renderCartPanel(false)}</div>`;}

  function renderSettings(){return `${pageHead('SHOP PROFILE','Settings','Set receipt details, tax, and data backup for this device.',`<button class="btn" data-action="load-demo">◈ Load sample shop</button>`)}<div class="settings-layout"><section class="panel"><div class="panel-head"><div><div class="panel-title">Shop details</div><div class="panel-subtitle">These details appear on printed receipts.</div></div></div><form id="settings-form"><div class="settings-group"><h3>Business identity</h3><div class="form-grid"><div class="field"><label>SHOP NAME</label><input name="shopName" value="${esc(db.settings.shopName)}" required /></div><div class="field"><label>SHOP PHONE</label><input name="phone" value="${esc(db.settings.phone)}" inputmode="tel" /></div><div class="field"><label>EMAIL</label><input name="email" value="${esc(db.settings.email)}" type="email" /></div><div class="field"><label>CURRENCY</label><select name="currency" ${db.sales.length?'disabled':''}>${CURRENCY_OPTIONS.map(c=>`<option ${db.settings.currency===c?'selected':''}>${c}</option>`).join('')}</select>${db.sales.length?`<small class="field-note">Currency is locked after the first sale so existing receipts remain accurate.</small>`:''}</div><div class="field full"><label>SHOP ADDRESS</label><textarea name="address">${esc(db.settings.address)}</textarea></div></div></div><div class="settings-group"><h3>Sales & stock rules</h3><div class="form-grid"><div class="field"><label>TAX RATE (%)</label><input name="taxRate" type="number" min="0" max="100" step="0.01" value="${Number(db.settings.taxRate)||0}" /><small class="field-note">Applied to new sales after discount. Set 0 if not applicable.</small></div><div class="field"><label>DEFAULT REORDER POINT</label><input name="lowStockDefault" type="number" min="0" step="1" value="${Number(db.settings.lowStockDefault)||0}" /><small class="field-note">Can be overridden for each part.</small></div><div class="field full"><label>RECEIPT FOOTER</label><textarea name="receiptNote">${esc(db.settings.receiptNote)}</textarea></div></div><div style="text-align:right;margin-top:15px"><button class="btn dark">Save shop settings →</button></div></div></form></section><div><section class="panel"><div class="panel-head"><div><div class="panel-title">Your shop data</div><div class="panel-subtitle">${db.products.length} parts · ${db.sales.length} sales · ${db.customers.length} saved customers</div></div></div><div class="settings-group"><h3>Backup & portability</h3><p class="settings-note">Download a complete backup before changing devices or clearing browser data. Restore will replace the records currently stored in this browser.</p><div class="settings-actions"><button class="btn" data-action="backup-json">↓ Download backup</button><button class="btn" data-action="restore-json">↑ Restore backup</button><input id="restore-file" class="hidden" type="file" accept="application/json,.json" /></div></div><div class="settings-group"><h3>Sample workspace</h3><p class="settings-note">Add clearly labeled example parts and transactions to explore the workflow. Remove the sample set later from this panel.</p><div class="settings-actions">${db.products.some(p=>p.isDemo)?`<button class="btn danger" data-action="remove-demo">Remove sample data</button>`:`<button class="btn" data-action="load-demo">＋ Add sample data</button>`}</div></div><div class="settings-group"><div class="warning-note"><strong>${serverMode?(storageMode==='mongodb'?'MongoDB storage.':'Private project folder storage.'):'Browser-only storage.'}</strong> ${serverMode?(storageMode==='mongodb'?'Shop records are stored in your configured MongoDB database and sync wherever this app is deployed.':'Shop records are saved as JSON in the project data folder, which you can open in VS Code.'):'Records are saved only in this browser profile.'} Keep a regular backup with the controls above.</div></div>${serverMode?'<div class="settings-group"><button class="btn" data-action="logout">Sign out</button></div>':''}</section><section class="panel section-gap"><div class="panel-head"><div><div class="panel-title">Data summary</div><div class="panel-subtitle">Current local workspace</div></div></div><div class="panel-body"><div class="total-row"><span>Inventory records</span><strong>${db.products.length}</strong></div><div class="total-row"><span>Stock movement entries</span><strong>${db.movements.length}</strong></div><div class="total-row"><span>Sales / receipts</span><strong>${db.sales.length}</strong></div><div class="total-row"><span>Customer records</span><strong>${db.customers.length}</strong></div></div></section></div></div>`;}

  function showModal(title,body,foot='',wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`;const first=$('input:not([type=hidden]),select,textarea',$('#modal-root'));if(first)setTimeout(()=>first.focus(),30);}
  function closeModal(){$('#modal-root').innerHTML='';}
  function showLogin(message=''){
    document.documentElement.classList.add('auth-pending');
    const errorCode=new URLSearchParams(location.search).get('auth_error');
    const oauthMessage=errorCode==='google_unavailable'?'Google sign-in is not configured yet. Use the admin password below.':errorCode==='google_denied'?'Google sign-in was cancelled. You can try again.':errorCode==='google_rejected'?'This Google account is not allowed to administer this shop.':errorCode==='google_failed'?'Google sign-in could not be completed. Try again or use the admin password.':'';
    const googleReady=document.documentElement.dataset.googleAuth==='enabled';
    const body=`<div class="eyebrow">GEARHOUSE · ADMIN ACCESS</div><p class="settings-note">Sign in to open the shop workspace.</p>${message||oauthMessage?`<div class="form-error">${esc(message||oauthMessage)}</div>`:''}${googleReady?`<a class="btn" style="width:100%;justify-content:center;margin:8px 0 14px" href="/api/auth/google/start">Continue with Google</a><div class="inline-note" style="text-align:center;margin-bottom:12px">or use your admin password</div>`:''}<form id="login-form"><div class="field"><label for="admin-password">ADMIN PASSWORD</label><input id="admin-password" name="password" type="password" autocomplete="current-password" required minlength="12" /></div></form>`;
    showModal('Admin sign in',body,`<span class="inline-note">Your session is private to this browser.</span><button class="btn dark" form="login-form">Sign in →</button>`);
    $('#modal-root .modal-close')?.remove();
  }
  async function loadServerWorkspace(){
    const response=await fetch('/api/state',{credentials:'same-origin',cache:'no-store'});
    if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.error||'Could not load the shop data.');}
    db=JSON.parse(JSON.stringify(await response.json()));
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db));}catch{}
    renderPage();
    if(!db.settings.demoSeeded&&db.products.length===0&&db.sales.length===0)loadDemo();
  }
  async function initializeServerMode(){
    renderPage();
    showLogin('Checking shop access…');
    try{
      const response=await fetch('/api/auth/session',{credentials:'same-origin',cache:'no-store'});
      if(response.ok){const info=await response.json().catch(()=>({}));storageMode=info.storage||storageMode;document.documentElement.dataset.googleAuth=info.googleConfigured?'enabled':'disabled';isAuthenticated=true;document.documentElement.classList.remove('auth-pending');closeModal();await loadServerWorkspace();return;}
      const info=await response.json().catch(()=>({}));
      document.documentElement.dataset.googleAuth=info.googleConfigured?'enabled':'disabled';
      showLogin(info.configured===false||response.status===503?'Admin sign-in or the data store is not configured. Set ADMIN_PASSWORD, SESSION_SECRET, and MONGODB_URI in the server environment.':'');
    }catch(error){showLogin('The app server is unavailable. Start the local app with npm start, then open its localhost address.');}
  }
  function openProductForm(product=null){const p=product||{name:'',sku:'',category:'Engine',brand:'',fitment:'',cost:'',price:'',quantity:0,reorderPoint:db.settings.lowStockDefault,location:'',notes:''};const editing=!!product;const body=`<form id="product-form"><input type="hidden" name="id" value="${esc(p.id||'')}"/><div class="form-grid"><div class="field full"><label>PART NAME *</label><input name="name" required maxlength="100" value="${esc(p.name)}" placeholder="e.g. Front brake pads" /></div><div class="field"><label>SKU / PART NUMBER</label><input name="sku" maxlength="60" value="${esc(p.sku)}" placeholder="e.g. BP-2048" /></div><div class="field"><label>CATEGORY</label><select name="category">${CATEGORIES.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>BRAND</label><input name="brand" value="${esc(p.brand)}" placeholder="Brand or manufacturer" /></div><div class="field"><label>VEHICLE FITMENT</label><input name="fitment" value="${esc(p.fitment)}" placeholder="Make, model, year" /></div><div class="field"><label>COST PRICE (${esc(db.settings.currency)})</label><input name="cost" type="number" min="0" step="0.01" value="${esc(p.cost)}" /></div><div class="field"><label>SELLING PRICE (${esc(db.settings.currency)}) *</label><input name="price" type="number" min="0" step="0.01" required value="${esc(p.price)}" /></div>${editing?'':`<div class="field"><label>OPENING STOCK *</label><input name="quantity" type="number" min="0" step="1" required value="${esc(p.quantity)}" /></div>`}<div class="field"><label>REORDER POINT</label><input name="reorderPoint" type="number" min="0" step="1" value="${esc(p.reorderPoint)}" /></div><div class="field full"><label>SHELF / BIN LOCATION</label><input name="location" value="${esc(p.location)}" placeholder="e.g. Aisle 2 · Bin B" /></div><div class="field full"><label>NOTES</label><textarea name="notes" placeholder="Optional details for your team">${esc(p.notes)}</textarea></div></div></form>`;
    const foot=`<span class="inline-note">${editing?'Update part details.':'Opening stock will be added to the stock movement log.'}</span><span class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn dark" form="product-form">${editing?'Save changes':'Add part'}</button></span>`;
    showModal(editing?'Edit part':'Add a part to inventory',body,foot,true);
  }
  function openAdjustForm(p){const body=`<form id="adjust-form"><input type="hidden" name="id" value="${p.id}"/><div class="inline-note" style="margin-bottom:14px">${esc(p.name)} · current balance <strong>${p.quantity}</strong> units</div><div class="form-grid"><div class="field"><label>CHANGE IN UNITS *</label><input name="delta" type="number" step="1" required placeholder="e.g. 12 or -1" /></div><div class="field"><label>REASON</label><select name="reason"><option>Stock received</option><option>Supplier return</option><option>Damage / write-off</option><option>Stock count correction</option><option>Other adjustment</option></select></div><div class="field full"><label>REFERENCE / NOTE</label><input name="note" placeholder="Supplier, invoice, or quick note" /></div></div><div class="inline-note" style="margin-top:12px">Use a positive number for stock received, or a negative number for a reduction. The balance cannot go below zero.</div></form>`;showModal('Adjust stock',body,`<span></span><span class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn dark" form="adjust-form">Save movement</button></span>`);}

  function addMovement(p,delta,reason,note=''){const before=Number(p.quantity)||0;p.quantity=before+delta;db.movements.push({id:uid(),productId:p.id,productName:p.name,delta,before,after:p.quantity,reason,note,date:new Date().toISOString()});}
  function nextReceipt(){const d=todayISO().replaceAll('-','').slice(2);const n=db.sales.filter(s=>localDateISO(s.date)===todayISO()).length+1;return `GH-${d}-${String(n).padStart(3,'0')}`;}
  function addCustomer(sale){const phone=(sale.customer?.phone||'').trim();if(!phone)return;const key=phone.replace(/\D/g,'');if(!key)return;let c=db.customers.find(x=>x.key===key);if(!c){c={id:uid(),key,name:sale.customer.name||'Customer',phone,email:sale.customer.email||'',createdAt:sale.date};db.customers.push(c);}else{if(sale.customer.name)c.name=sale.customer.name;if(sale.customer.email)c.email=sale.customer.email;}}
  function createSale(){
    if(!cart.length){toast('Add a part before completing the sale.','error');return;}
    for(const line of cart){const p=productById(line.productId);if(!p||p.active===false||p.quantity<line.qty){toast(`${line.name} no longer has enough stock.`,'error');renderPage();return;}}
    const totals=cartTotals();if(totals.discount>totals.subtotal){toast('Discount cannot be greater than the subtotal.','error');return;}
    const customer={name:$('#customer-name')?.value.trim()||'',phone:$('#customer-phone')?.value.trim()||'',email:$('#customer-email')?.value.trim()||''};
    const sale={id:uid(),receiptNo:nextReceipt(),date:new Date().toISOString(),customer,items:cart.map(l=>({productId:l.productId,name:l.name,sku:l.sku,qty:l.qty,price:l.price})),subtotal:totals.subtotal,discount:totals.discount,tax:totals.tax,taxRate:Number(db.settings.taxRate)||0,total:totals.total,paymentMethod:$('#payment-method')?.value||'Cash',status:'paid'};
    sale.items.forEach(line=>{const p=productById(line.productId);addMovement(p,-line.qty,`Sale ${sale.receiptNo}`,customer.name||'Walk-in customer');});
    db.sales.push(sale);addCustomer(sale);saveDB();cart=[];receiptSaleId=sale.id;page='sales';$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb-page').textContent=PAGE_NAMES[page];renderPage();toast(`Sale saved · ${sale.receiptNo}`);
  }
  function voidSale(id){const s=db.sales.find(x=>x.id===id);if(!s||s.status==='void')return;if(!window.confirm(`Void ${s.receiptNo}? This marks the receipt void and restores its items to stock.`))return;s.status='void';s.items.forEach(i=>{const p=productById(i.productId);if(p)addMovement(p,i.qty,`Void ${s.receiptNo}`,'Sale reversed');});saveDB();renderPage();toast('Sale voided and stock restored.');}

  function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function csv(rows){return rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');}
  function exportProducts(){download('gearhouse-inventory.csv',csv([['SKU','Part name','Category','Brand','Fitment','Cost','Price','Quantity','Reorder point','Location','Active'],...db.products.map(p=>[p.sku,p.name,p.category,p.brand,p.fitment,p.cost,p.price,p.quantity,p.reorderPoint,p.location,p.active!==false])]),'text/csv;charset=utf-8');}
  function exportSales(){download('gearhouse-sales.csv',csv([['Receipt','Date','Customer','Phone','Items','Subtotal','Discount','Tax','Total','Payment','Status'],...db.sales.map(s=>[s.receiptNo,s.date,s.customer?.name,s.customer?.phone,s.items.map(i=>`${i.name} x${i.qty}`).join('; '),s.subtotal,s.discount,s.tax,s.total,s.paymentMethod,s.status])]),'text/csv;charset=utf-8');}
  function exportCustomers(){download('gearhouse-customers.csv',csv([['Name','Phone','Email','Visits','Lifetime spend','Last visit'],...customersFromSalesNoFilter().map(c=>[c.name,c.phone,c.email,c.visits,c.totalSpent,c.lastVisit])]),'text/csv;charset=utf-8');}
  function safeRestore(data){if(!data||typeof data!=='object'||!Array.isArray(data.products)||!Array.isArray(data.sales)||!Array.isArray(data.movements))throw new Error('This file does not look like a Gearhouse backup.');const next={...structuredClone(DEFAULTS),...data,settings:{...DEFAULTS.settings,...(data.settings||{})},customers:Array.isArray(data.customers)?data.customers:[],orders:Array.isArray(data.orders)?data.orders:[]};if(next.products.some(p=>!p.id||typeof p.name!=='string')||next.sales.some(s=>!s.id||!Array.isArray(s.items)))throw new Error('The backup has incomplete records.');return next;}
  function loadDemo(){
    if(db.products.some(p=>p.isDemo)){toast('Sample data is already loaded.');return;}
    if(db.products.length||db.sales.length){if(!window.confirm('Sample parts and sales will be added to your existing workspace. Continue?'))return;}
    const parts=[['Oil filter · Spin-on','FILTER-OF118','Filters','Bosch','Maruti Swift / Dzire',210,340,14,5,'A1-04'],['Front brake pads · Ceramic','BRAKE-FP204','Brakes','Brembo','Hyundai i20 2015–20',850,1250,8,4,'B2-11'],['12V headlamp bulb · H4','ELEC-H4-12','Electrical','Philips','Universal H4 socket',190,320,3,5,'C1-02'],['Engine air filter','FILTER-AF052','Filters','Mann','Honda City 2014–19',330,520,11,4,'A1-07'],['Coolant · 1 litre','COOL-LL01','Cooling','Castrol','Universal',175,260,20,6,'D3-01'],['Drive belt · 6PK','ENG-6PK1280','Engine','Gates','Tata Nexon petrol',490,760,2,3,'A3-08']];
    parts.forEach(([name,sku,category,brand,fitment,cost,price,quantity,reorderPoint,location])=>{const p={id:uid(),name,sku,category,brand,fitment,cost,price,quantity:0,reorderPoint,location,notes:'Example record — replace with your shop data.',active:true,isDemo:true,createdAt:new Date().toISOString()};db.products.push(p);if(quantity)addMovement(p,quantity,'Sample opening stock','Example data');});
    const sample=activeProducts().slice(0,2);if(sample.length===2){const items=[{productId:sample[0].id,name:sample[0].name,sku:sample[0].sku,qty:1,price:sample[0].price}];const sub=items[0].price;const s={id:uid(),receiptNo:nextReceipt(),date:new Date(Date.now()-86400000).toISOString(),customer:{name:'Sample customer',phone:'0000000000',email:''},items,subtotal:sub,discount:0,tax:0,taxRate:0,total:sub,paymentMethod:'Cash',status:'paid',isDemo:true};sample[0].quantity--;db.sales.push(s);db.movements.push({id:uid(),productId:sample[0].id,productName:sample[0].name,delta:-1,before:sample[0].quantity+1,after:sample[0].quantity,reason:`Sale ${s.receiptNo}`,note:'Example data',date:s.date});}
    db.settings.demoSeeded=true;saveDB();renderPage();toast('Sample shop data added.');
  }
  function removeDemo(){if(!window.confirm('Remove all sample parts, sample sales, and related movement entries?'))return;const ids=new Set(db.products.filter(p=>p.isDemo).map(p=>p.id));const saleIds=new Set(db.sales.filter(s=>s.isDemo).map(s=>s.id));db.products=db.products.filter(p=>!ids.has(p.id));db.sales=db.sales.filter(s=>!saleIds.has(s.id));db.movements=db.movements.filter(m=>!ids.has(m.productId)&&![...saleIds].some(id=>m.reason.includes(id)));db.customers=db.customers.filter(c=>c.phone!=='0000000000');saveDB();renderPage();toast('Sample data removed.');}

  function handleClick(e){
    const nav=e.target.closest('[data-page]');if(nav){setPage(nav.dataset.page);return;}
    const go=e.target.closest('[data-go]');if(go){setPage(go.dataset.go);return;}
    const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;const id=b.dataset.id;
    if(action==='new-product'){openProductForm();return;}if(action==='close-modal'){if(serverMode&&!isAuthenticated)return;closeModal();return;}if(action==='backdrop-close'&&e.target===b){if(serverMode&&!isAuthenticated)return;closeModal();return;}
    if(action==='edit-product'){const p=productById(id);if(p)openProductForm(p);return;}
    if(action==='adjust-stock'){const p=productById(id);if(p)openAdjustForm(p);return;}
    if(action==='archive-product'){const p=productById(id);if(!p)return;showModal('Part actions',`<p class="settings-note">${esc(p.name)} currently has <strong>${p.quantity}</strong> units. Archived parts are removed from checkout and the customer catalog, while old receipts remain readable.</p>`,`<button class="btn" data-action="close-modal">Cancel</button><span class="modal-actions"><button class="btn dark" data-action="archive-confirm" data-id="${p.id}">Archive part</button></span>`);return;}
    if(action==='archive-confirm'){const p=productById(id);if(p){p.active=false;saveDB();closeModal();renderPage();toast('Part archived.');}return;}
    if(action==='restore-product'){const p=productById(id);if(p){p.active=true;saveDB();renderPage();toast('Part restored to active inventory.');}return;}
    if(action==='cart-add'){const p=productById(id);if(!p||p.active===false)return;const line=cart.find(l=>l.productId===p.id);if((line?.qty||0)>=p.quantity){toast('That is all the available stock.','error');return;}if(line)line.qty++;else cart.push({productId:p.id,name:p.name,sku:p.sku,price:Number(p.price)||0,qty:1});renderPage();return;}
    if(action==='cart-qty'){const line=cart.find(l=>l.productId===id);const p=productById(id);if(!line)return;const n=line.qty+Number(b.dataset.step);if(n<=0)cart=cart.filter(x=>x!==line);else if(p&&n<=p.quantity)line.qty=n;else toast('Quantity exceeds stock on hand.','error');renderPage();return;}
    if(action==='cart-remove'){cart=cart.filter(l=>l.productId!==id);renderPage();return;}
    if(action==='cart-clear'){cart=[];renderPage();return;}
    if(action==='checkout'){createSale();return;}if(action==='catalog-checkout'){setPage('pos');toast('Add customer details and complete the sale at the counter.');return;}
    if(action==='view-receipt'){receiptSaleId=id;renderPage();return;}if(action==='print-receipt'){window.print();return;}if(action==='void-sale'){voidSale(id);return;}
    if(action==='sales-filter'){salesFilter=b.dataset.value;renderPage();return;}
    if(action==='set-order-status'){const order=db.orders.find(o=>o.id===id);const next=b.dataset.status;if(order&&['new','contacted','ready','completed','cancelled'].includes(next)){order.status=next;order.statusUpdatedAt=new Date().toISOString();saveDB();renderPage();toast('Customer request updated.');}return;}
    if(action==='customer-history'){const phone=b.dataset.phone;const entries=db.sales.filter(s=>s.customer?.phone===phone);showModal('Customer sales',`<div class="inline-note" style="margin-bottom:12px">${esc(phone)} · ${entries.length} sale${entries.length===1?'':'s'}</div><div class="activity-list">${entries.sort((a,z)=>new Date(z.date)-new Date(a.date)).map(s=>`<div class="activity-row"><div class="activity-badge">↗</div><div class="activity-copy"><strong>${esc(s.receiptNo)} · ${dateOnly(s.date)}</strong><small>${s.items.map(i=>`${esc(i.name)} × ${i.qty}`).join(', ')}</small></div><span class="activity-amount">${money(s.total)}</span><button class="text-action" data-action="view-receipt" data-id="${s.id}">Open</button></div>`).join('')||'<p class="inline-note">No paid sales found.</p>'}</div>`,`<span></span><button class="btn" data-action="close-modal">Close</button>`,true);return;}
    if(action==='export-products'){exportProducts();return;}if(action==='export-sales'){exportSales();return;}if(action==='export-customers'){exportCustomers();return;}
    if(action==='backup-json'){download('gearhouse-backup-'+todayISO()+'.json',JSON.stringify({...db,backupVersion:1,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Backup downloaded.');return;}
    if(action==='logout'){if(!window.confirm('Sign out of this shop workspace?'))return;fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'}).finally(()=>{isAuthenticated=false;showLogin();});return;}
    if(action==='restore-json'){$('#restore-file').click();return;}
    if(action==='load-demo'){loadDemo();return;}if(action==='remove-demo'){removeDemo();return;}
  }

  async function handleSubmit(e){
    if(e.target.id==='login-form'){
      e.preventDefault();const password=new FormData(e.target).get('password');const button=$('button[form="login-form"]');if(button){button.disabled=true;button.textContent='Signing in…';}
      try{const response=await fetch('/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({password})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Could not sign in.');isAuthenticated=true;document.documentElement.classList.remove('auth-pending');closeModal();await loadServerWorkspace();}
      catch(error){showLogin(error.message);}
      return;
    }
    if(e.target.id==='product-form'){e.preventDefault();const f=new FormData(e.target);const id=f.get('id');const name=String(f.get('name')).trim();const sku=String(f.get('sku')).trim();const price=Number(f.get('price'));const cost=Number(f.get('cost'))||0;const quantity=Number(f.get('quantity')||0);if(!name||!Number.isFinite(price)||price<0||cost<0||quantity<0||!Number.isInteger(quantity)){toast('Enter a valid part name, non-negative price, and whole-number quantity.','error');return;}if(sku&&db.products.some(p=>p.sku.toLowerCase()===sku.toLowerCase()&&p.id!==id)){toast('That SKU is already in use.','error');return;}const fields={name,sku,category:String(f.get('category')),brand:String(f.get('brand')).trim(),fitment:String(f.get('fitment')).trim(),cost,price,reorderPoint:Math.max(0,Number(f.get('reorderPoint'))||0),location:String(f.get('location')).trim(),notes:String(f.get('notes')).trim()};if(id){const p=productById(id);Object.assign(p,fields);}else{const p={id:uid(),...fields,quantity:0,active:true,createdAt:new Date().toISOString()};db.products.push(p);if(quantity)addMovement(p,quantity,'Opening stock','Initial inventory entry');}saveDB();closeModal();renderPage();toast(id?'Part updated.':'Part added to inventory.');return;}
    if(e.target.id==='adjust-form'){e.preventDefault();const f=new FormData(e.target);const p=productById(String(f.get('id')));const delta=Number(f.get('delta'));if(!p||!Number.isInteger(delta)||delta===0){toast('Enter a non-zero whole number of units.','error');return;}if(p.quantity+delta<0){toast('That change would make stock negative.','error');return;}addMovement(p,delta,String(f.get('reason')),String(f.get('note')).trim());saveDB();closeModal();renderPage();toast('Stock movement recorded.');return;}
    if(e.target.id==='settings-form'){e.preventDefault();const f=new FormData(e.target);const tax=Number(f.get('taxRate'));const reorder=Number(f.get('lowStockDefault'));if(!Number.isFinite(tax)||tax<0||tax>100||!Number.isFinite(reorder)||reorder<0){toast('Enter a valid tax rate and reorder point.','error');return;}db.settings={...db.settings,shopName:String(f.get('shopName')).trim()||'GEARHOUSE',phone:String(f.get('phone')).trim(),email:String(f.get('email')).trim(),address:String(f.get('address')).trim(),currency:String(f.get('currency')||db.settings.currency),taxRate:tax,lowStockDefault:Math.floor(reorder),receiptNote:String(f.get('receiptNote')).trim()};saveDB();$('#brand-name').textContent=db.settings.shopName.toUpperCase();renderPage();toast('Shop settings saved.');return;}
  }
  function refreshCartTotals(){const t=cartTotals();const set=(sel,val)=>{const x=$(sel);if(x)x.textContent=val;};set('#subtotal-val',money(t.subtotal));set('#discount-val','− '+money(t.discount));set('#tax-val',money(t.tax));set('#grand-val',money(t.total));}

  document.addEventListener('click',handleClick);
  document.addEventListener('submit',handleSubmit);
  document.addEventListener('input',e=>{
    if(e.target.id==='inventory-search'){inventoryQuery=e.target.value;const caret=e.target.selectionStart;renderPage();const n=$('#inventory-search');n.focus();n.setSelectionRange(caret,caret);}
    else if(e.target.id==='pos-search'){posQuery=e.target.value;const caret=e.target.selectionStart;renderPage();const n=$('#pos-search');n.focus();n.setSelectionRange(caret,caret);}
    else if(e.target.id==='store-search'){storeQuery=e.target.value;const caret=e.target.selectionStart;renderPage();const n=$('#store-search');n.focus();n.setSelectionRange(caret,caret);}
    else if(e.target.id==='customer-search'){customerQuery=e.target.value;const caret=e.target.selectionStart;renderPage();const n=$('#customer-search');n.focus();n.setSelectionRange(caret,caret);}
    else if(e.target.id==='discount-input')refreshCartTotals();
  });
  document.addEventListener('change',e=>{
    if(e.target.id==='inventory-filter'){inventoryFilter=e.target.value;renderPage();}
    if(e.target.id==='orders-filter'){orderFilter=e.target.value;renderPage();}
    if(e.target.id==='restore-file'&&e.target.files?.[0]){const file=e.target.files[0];const reader=new FileReader();reader.onload=()=>{try{const next=safeRestore(JSON.parse(reader.result));if(!window.confirm(`Restore ${next.products.length} parts and ${next.sales.length} sales? This replaces current local records.`))return;db=next;saveDB();renderPage();toast('Backup restored.');}catch(err){toast(err.message||'Could not restore this file.','error');}};reader.readAsText(file);e.target.value='';}
  });
  $('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
  $('#top-search-btn').addEventListener('click',()=>{setPage('inventory');setTimeout(()=>$('#inventory-search')?.focus(),60);});
  $('#today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'}).toUpperCase();
  $('#brand-name').textContent=(db.settings.shopName||'GEARHOUSE').toUpperCase();
  if(serverMode)initializeServerMode();
  else {renderPage();if(!db.settings.demoSeeded&&db.products.length===0&&db.sales.length===0)loadDemo();}
})();
